INSERT INTO permission (code,name,module,description,active) SELECT v.code,v.name,'PERSONNEL',v.description,TRUE FROM (VALUES
('PERSONNEL_CONSULTER','Consulter le personnel','Consulter les dossiers du personnel'),
('PERSONNEL_CREER','Créer un employé','Créer un dossier employé'),
('PERSONNEL_MODIFIER','Modifier un employé','Modifier les informations RH'),
('PERSONNEL_NOTES_GERER','Gérer les notes RH','Gérer les observations administratives sensibles'),
('PERSONNEL_DASHBOARD','Tableau de bord RH','Consulter les indicateurs personnel et enseignants'),
('ENSEIGNANT_CONSULTER','Consulter les enseignants','Consulter les enseignants et leurs matières'),
('ENSEIGNANT_CREER','Créer un enseignant','Créer le profil enseignant depuis un employé'),
('ENSEIGNANT_MODIFIER','Modifier un enseignant','Modifier le statut enseignant'),
('ENSEIGNANT_AFFECTER','Affecter un enseignant','Gérer matières, classes et affectations pédagogiques'),
('REMUNERATION_CONSULTER','Consulter la rémunération','Consulter plans et tarifs enseignants'),
('REMUNERATION_GERER','Gérer la rémunération','Créer plans mensuels, horaires ou mixtes et grilles tarifaires')
INSERT INTO role_permission(role_id,permission_id) SELECT r.id,p.id FROM role r CROSS JOIN permission p WHERE r.code='ADMIN' AND p.module='PERSONNEL' AND NOT EXISTS (SELECT 1 FROM role_permission rp WHERE rp.role_id=r.id AND rp.permission_id=p.id);
INSERT INTO role_permission(role_id,permission_id) SELECT r.id,p.id FROM role r CROSS JOIN permission p WHERE r.code='DIRECTEUR_PEDAGOGIQUE' AND p.code IN ('PERSONNEL_CONSULTER','PERSONNEL_DASHBOARD','ENSEIGNANT_CONSULTER','ENSEIGNANT_AFFECTER','REMUNERATION_CONSULTER') AND NOT EXISTS (SELECT 1 FROM role_permission rp WHERE rp.role_id=r.id AND rp.permission_id=p.id);
